function przyklad() {
  var a = 1;

  if (true) {
    var b = 2;        // wciaz w zasiegu funkcji przyklad()
  }

  for (var c = 0; c < 1; c++) {
    var d = 3;        // rowniez w zasiegu funkcji przyklad()
  }

  console.log(a, b, c, d); // 1 2 1 3 - WSZYSTKIE dostepne tutaj
}

przyklad();
// console.log(a); // ReferenceError - a NIE istnieje poza funkcja przyklad()

function sprawdzStatus(saldo) {
  if (saldo > 0) {
    var status = "aktywny";
  } else {
    var status = "zablokowany";
  }

  console.log("Status konta:", status); // dziala - var 'wyciekl' z if/else
  return status;
}

sprawdzStatus(100); // Status konta: aktywny
sprawdzStatus(-5);  // Status konta: zablokowany

for (var i = 0; i < 3; i++) {
  setTimeout(function () {
    console.log(i);
  }, 100);
}
// BLEDNIE wypisuje: 3, 3, 3
// (zamiast oczekiwanego 0, 1, 2) - wszystkie trzy funkcje
// odwoluja sie do TEJ SAMEJ, wspolnej zmiennej i

for (var i = 0; i < 3; i++) {
  (function (kopiaI) {
    setTimeout(function () {
      console.log(kopiaI);
    }, 100);
  })(i); // i przekazane JAKO ARGUMENT - kazde wywolanie dostaje WLASNA kopie
}
// POPRAWNIE wypisuje: 0, 1, 2
// kazde wywolanie IIFE tworzy NOWY parametr kopiaI,
// niezalezny od kolejnych iteracji petli

