function sprawdzStatus() {
  if (true) {
    var status = "aktywny";
  }
  console.log(status); // "aktywny"
}

sprawdzStatus();

function liczPetle() {
  for (var i = 0; i < 3; i++) {
    // pusta petla
  }
  console.log(i); // 3
}

liczPetle();

function zmienStan() {
  var stan = "start";
  for (var i = 0; i < 3; i++) {
    stan = "koniec";
  }
  console.log(stan); // "koniec"
}

zmienStan();

var x = "globalny";

function test() {
  var x = "lokalny";
  console.log(x); // "lokalny"
}

test();
console.log(x); // "globalny" - NIE zostalo nadpisane

var x = "globalny";

function test() {
  x = "lokalny"; // BEZ var - modyfikuje ZEWNETRZNA zmienna x
  console.log(x); // "lokalny"
}

test();
console.log(x); // "lokalny" - zewnetrzna zmienna ZOSTALA nadpisana,
// bo bez 'var' silnik JS uzyl istniejacej zmiennej z zewnetrznego zasiegu

var licznik = 0;

function zwiekszLicznik() {
  licznik = licznik + 1;
  console.log(licznik);
}

zwiekszLicznik(); // 1
zwiekszLicznik(); // 2
zwiekszLicznik(); // 3

function porownajZasiegi() {
  if (true) {
    var wynik = "pierwszy";
  }
  if (true) {
    var wynik = "drugi";
  }
  console.log(wynik); // "drugi" - obie deklaracje to TA SAMA zmienna
}

porownajZasiegi();

function sumujTablice(liczby) {
  var suma = 0;
  for (var i = 0; i < liczby.length; i++) {
    suma = suma + liczby[i];
  }
  return suma;
}

console.log(sumujTablice([1, 2, 3, 4, 5])); // 15

var funkcje = [];

for (var i = 0; i < 3; i++) {
  funkcje.push(() => console.log(i));
}

funkcje[0](); // 3
funkcje[1](); // 3
funkcje[2](); // 3
// wszystkie funkcje 'widza' ostateczna wartosc i po zakonczeniu petli (3),
// nie wartosc z momentu, w ktorym zostaly utworzone

var funkcje = [];

for (var i = 0; i < 3; i++) {
  (function (kopiaI) {
    funkcje.push(() => console.log(kopiaI));
  })(i);
}

funkcje[0](); // 0
funkcje[1](); // 1
funkcje[2](); // 2

function pierwsza() {
  var wartosc = 10;
  wartosc = 20;
  console.log("pierwsza:", wartosc); // 20
}

function druga() {
  var wartosc = 10;
  wartosc = 30;
  console.log("druga:", wartosc); // 30
}

pierwsza();
druga();

var typ = 100;
console.log(typeof typ, typ); // number 100

typ = "sto";
console.log(typeof typ, typ); // string sto

typ = true;
console.log(typeof typ, typ); // boolean true
// mozliwe, bo JavaScript nie wiaze zmiennej ze stalym typem -
// zmienna to tylko 'etykieta', ktora moze wskazywac na wartosc dowolnego typu

function proboweSumowanie() {
  try {
    var wynik = 1 + 1;
  } catch (e) {
    var wynik = 0;
  }
  console.log(wynik); // 2
}

proboweSumowanie();
// dziala - var zadeklarowany w bloku try jest dostepny w calej funkcji,
// bo try/catch NIE jest granica zasiegu dla var

for (var i = 0; i < 2; i++) {
  for (var i = 0; i < 2; i++) {
    // ta sama zmienna i co w zewnetrznej petli!
  }
}
console.log(i); // 2
// wewnetrzna petla dzieli TA SAMA zmienna i z zewnetrzna -
// to klasyczny powod, dla ktorego zagniezdzone petle var-owe
// sa zrodlem trudnych do znalezienia bledow

const konfiguracja = { tryb: "produkcja" };

function wczytajTryb() {
  if (konfiguracja) {
    var wynik = konfiguracja.tryb;
  }
  return wynik;
}

console.log(wczytajTryb()); // "produkcja"

